import{_ as s,o as e,c as n,a6 as p}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"代理缓存","description":"proxy_cache_path 全参数、缓存键的默认值陷阱、优先级链、锁与后台更新、stale 兜底。","frontmatter":{"title":"代理缓存","description":"proxy_cache_path 全参数、缓存键的默认值陷阱、优先级链、锁与后台更新、stale 兜底。","source":"https://daiw.org/manual/nginx/caching"},"headers":[],"relativePath":"manual/tools/nginx/caching.md","filePath":"manual/tools/nginx/caching.md"}'),t={name:"manual/tools/nginx/caching.md"};function i(c,a,r,l,o,d){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="代理缓存" tabindex="-1">代理缓存 <a class="header-anchor" href="#代理缓存" aria-label="Permalink to &quot;代理缓存&quot;">​</a></h1><h2 id="proxy-cache-path" tabindex="-1">proxy_cache_path <a class="header-anchor" href="#proxy-cache-path" aria-label="Permalink to &quot;proxy\\_cache\\_path&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    proxy_cache_path path [levels=levels] [keys_zone=name:size]</span></span>
<span class="line"><span>                          [inactive=time] [max_size=size]</span></span>
<span class="line"><span>                          [use_temp_path=on|off] [min_free=size] ...;</span></span>
<span class="line"><span>上下文:  http</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>只能写在 <code>http</code> 上下文</strong>（它定义的是全局共享资源）。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_path /data/nginx/cache</span></span>
<span class="line"><span>                 levels=1:2</span></span>
<span class="line"><span>                 keys_zone=one:10m</span></span>
<span class="line"><span>                 inactive=60m</span></span>
<span class="line"><span>                 max_size=1g;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><code>levels</code></td><td>目录层级，每级 1 或 2 位，最多 3 级</td></tr><tr><td><code>keys_zone=名:大小</code></td><td><strong>共享内存区</strong>，存键与元数据。<strong>1 MB ≈ 8000 个键</strong></td></tr><tr><td><code>inactive</code></td><td>多久没被访问就删除，<strong>默认 10 分钟</strong></td></tr><tr><td><code>max_size</code></td><td>磁盘上限，超了由 cache manager 清理</td></tr><tr><td><code>use_temp_path</code></td><td>是否用独立临时目录，<strong>默认 on</strong></td></tr><tr><td><code>min_free</code></td><td>文件系统最小剩余空间（1.19.1+）</td></tr></tbody></table><h3 id="levels-为什么需要" tabindex="-1">levels 为什么需要 <a class="header-anchor" href="#levels-为什么需要" aria-label="Permalink to &quot;levels 为什么需要&quot;">​</a></h3><p>不分层的话所有缓存文件堆在一个目录里，几十万文件会让文件系统查找变得极慢。<code>levels=1:2</code> 表示按哈希值切出「1 位 / 2 位」两级子目录：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/nginx/cache/c/29/b7f54b2df7773722d382f4809d65029c</span></span>
<span class="line"><span>                  ^ ^^</span></span>
<span class="line"><span>                  1  2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="keys-zone-要多大" tabindex="-1">keys_zone 要多大 <a class="header-anchor" href="#keys-zone-要多大" aria-label="Permalink to &quot;keys\\_zone 要多大&quot;">​</a></h3><p><strong>只存键和元数据，不存内容</strong>。按 1 MB ≈ 8000 键估算：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10m  → 约 8 万个缓存对象</span></span>
<span class="line"><span>100m → 约 80 万个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>zone 满了会按 LRU 淘汰</strong>——即使磁盘还有空间。所以 <code>keys_zone</code> 与 <code>max_size</code> 要匹配：平均对象 20 KB 时，<code>max_size=1g</code> 对应约 5 万对象，<code>keys_zone=10m</code> 够用。</p><h3 id="use-temp-path" tabindex="-1">use_temp_path <a class="header-anchor" href="#use-temp-path" aria-label="Permalink to &quot;use\\_temp\\_path&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use_temp_path=off</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>建议设为 off</strong>。默认 <code>on</code> 时，响应先写到 <code>proxy_temp_path</code>，再<strong>移动</strong>到缓存目录。如果两者不在同一个文件系统，「移动」变成「跨设备复制」——白白多一次完整 IO。</p><p>设 off 让 nginx 直接写在缓存目录下的临时文件里，然后原地 rename。</p><h2 id="proxy-cache" tabindex="-1">proxy_cache <a class="header-anchor" href="#proxy-cache" aria-label="Permalink to &quot;proxy\\_cache&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    proxy_cache zone | off;</span></span>
<span class="line"><span>默认:    proxy_cache off;</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache one;   # 引用 keys_zone 里定义的名字</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>默认关闭</strong>——定义了 <code>proxy_cache_path</code> 不等于启用了缓存，还必须在需要的地方写 <code>proxy_cache</code>。</p><h2 id="proxy-cache-key" tabindex="-1">proxy_cache_key <a class="header-anchor" href="#proxy-cache-key" aria-label="Permalink to &quot;proxy\\_cache\\_key&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    proxy_cache_key string;</span></span>
<span class="line"><span>默认:    proxy_cache_key $scheme$proxy_host$request_uri;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>默认键里没有 <code>$host</code>，只有 <code>$proxy_host</code>。</strong></p><p><code>$proxy_host</code> 是 <a href="/Front2Full/manual/tools/nginx/proxy"><code>proxy_pass</code> 里写的上游名</a>，不是客户端请求的域名。所以<strong>多个域名共用同一个 upstream 时，它们的缓存会互相串</strong>——<code>a.example.com/x</code> 与 <code>b.example.com/x</code> 命中同一条缓存。</p><p>多域名场景必须改：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_key &quot;$scheme$host$request_uri&quot;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>内容协商也要进键。若上游按 <code>Accept-Encoding</code> 返回不同编码，键里没有它就会把 gzip 版发给不支持的客户端——这与 <a href="https://daiw.org/manual/http11/content-negotiation" target="_blank" rel="noreferrer">HTTP 的 <code>Vary</code> 语义</a>是同一个问题。nginx 会<strong>自动尊重上游的 <code>Vary</code> 头</strong>，但如果上游没发 <code>Vary</code>，就得自己把维度加进键。</p><h2 id="proxy-cache-valid-与优先级链" tabindex="-1">proxy_cache_valid 与优先级链 <a class="header-anchor" href="#proxy-cache-valid-与优先级链" aria-label="Permalink to &quot;proxy\\_cache\\_valid 与优先级链&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_valid 200 302 10m;</span></span>
<span class="line"><span>proxy_cache_valid 404      1m;</span></span>
<span class="line"><span>proxy_cache_valid any      1m;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>不写状态码时<strong>只对 200、301、302 生效</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_valid 5m;   # 等价于 proxy_cache_valid 200 301 302 5m;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>缓存时长的优先级链</strong>（官方顺序）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. X-Accel-Expires（上游响应头，秒；nginx 私有）</span></span>
<span class="line"><span>2. Expires 或 Cache-Control（上游响应头）</span></span>
<span class="line"><span>3. proxy_cache_valid（nginx 配置）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>上游的头优先于 nginx 配置。</strong> 所以 <code>proxy_cache_valid 200 10m;</code> 未必生效——上游发了 <code>Cache-Control: no-store</code> 就不会缓存。</p><p>要<strong>强制忽略上游的缓存头</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_ignore_headers Cache-Control Expires Set-Cookie;</span></span>
<span class="line"><span>proxy_cache_valid 200 10m;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>proxy_ignore_headers Set-Cookie</code> 要极其小心——忽略它意味着<strong>带 <code>Set-Cookie</code> 的响应也会被缓存</strong>，可能把一个用户的会话 Cookie 发给其他用户。只在确认上游不会返回用户相关内容时才用。</p><h2 id="缓存击穿防护" tabindex="-1">缓存击穿防护 <a class="header-anchor" href="#缓存击穿防护" aria-label="Permalink to &quot;缓存击穿防护&quot;">​</a></h2><h3 id="proxy-cache-lock" tabindex="-1">proxy_cache_lock <a class="header-anchor" href="#proxy-cache-lock" aria-label="Permalink to &quot;proxy\\_cache\\_lock&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    proxy_cache_lock on | off;</span></span>
<span class="line"><span>默认:    proxy_cache_lock off;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>默认关闭</strong>。关闭时，一个热点对象过期的瞬间，所有并发请求会<strong>同时</strong>打到上游——即缓存击穿。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_lock         on;</span></span>
<span class="line"><span>proxy_cache_lock_timeout 5s;   # 默认 5s</span></span>
<span class="line"><span>proxy_cache_lock_age     5s;   # 默认 5s，超时后允许第二个请求去回源</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>开启后只有第一个请求回源，其余等待。<code>lock_age</code> 是保险丝：第一个请求太慢时放第二个过去，避免全部堵死。</p><p>注意 <code>lock_timeout</code> 超时后的行为：<strong>该响应不会被缓存</strong>。</p><h3 id="proxy-cache-use-stale" tabindex="-1">proxy_cache_use_stale <a class="header-anchor" href="#proxy-cache-use-stale" aria-label="Permalink to &quot;proxy\\_cache\\_use\\_stale&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>默认:    proxy_cache_use_stale off;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_use_stale error timeout updating http_500 http_502 http_503 http_504;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>上游出问题时继续返回过期内容</strong>——比返回 502 好得多。</p><p><code>updating</code> 参数特别重要：<strong>正在更新时，其他请求直接拿旧的</strong>，不必等待。它与 <code>proxy_cache_lock</code> 是两种思路（等 vs 用旧的），<code>updating</code> 对用户体验更好。</p><p>nginx 也支持上游用 <a href="https://daiw.org/manual/http11/caching" target="_blank" rel="noreferrer">RFC 5861 的 <code>stale-while-revalidate</code> / <code>stale-if-error</code></a> 来控制这一行为。</p><h3 id="proxy-cache-background-update" tabindex="-1">proxy_cache_background_update <a class="header-anchor" href="#proxy-cache-background-update" aria-label="Permalink to &quot;proxy\\_cache\\_background\\_update&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>默认:    proxy_cache_background_update off;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_use_stale        updating;</span></span>
<span class="line"><span>proxy_cache_background_update on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>先把过期内容返回给用户，后台异步去更新</strong>。用户永远不等待回源——这是「陈旧但快」优于「新鲜但慢」的典型取舍。</p><p><strong>必须与 <code>proxy_cache_use_stale updating</code> 一起配</strong>，单独开不生效。</p><h2 id="proxy-cache-revalidate" tabindex="-1">proxy_cache_revalidate <a class="header-anchor" href="#proxy-cache-revalidate" aria-label="Permalink to &quot;proxy\\_cache\\_revalidate&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>默认:    proxy_cache_revalidate off;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_revalidate on;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>开启后，缓存过期时发**<a href="https://daiw.org/manual/http11/conditional-requests" target="_blank" rel="noreferrer">条件请求</a>**（带 <code>If-None-Match</code> / <code>If-Modified-Since</code>）而不是完整请求。上游若返回 <code>304</code>，nginx 直接续期本地副本——<strong>省掉一次完整传输</strong>。</p><p>对大文件收益巨大。<strong>建议总是开启</strong>。</p><h2 id="绕过与不缓存" tabindex="-1">绕过与不缓存 <a class="header-anchor" href="#绕过与不缓存" aria-label="Permalink to &quot;绕过与不缓存&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_bypass $cookie_nocache $arg_nocache $http_pragma;</span></span>
<span class="line"><span>proxy_no_cache     $cookie_nocache $arg_nocache $http_authorization;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>两者容易混：</p><table tabindex="0"><thead><tr><th>指令</th><th>含义</th></tr></thead><tbody><tr><td><code>proxy_cache_bypass</code></td><td><strong>不查</strong>缓存（直接回源），但<strong>结果仍会存</strong>进缓存</td></tr><tr><td><code>proxy_no_cache</code></td><td><strong>不存</strong>缓存（可能仍会查）</td></tr></tbody></table><p><strong>判定规则</strong>：任一参数非空且不等于 <code>&quot;0&quot;</code> 就触发。</p><p>要「既不查也不存」两个都写。典型用于登录用户：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_cache_bypass $http_authorization;</span></span>
<span class="line"><span>proxy_no_cache     $http_authorization;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这与 <a href="https://daiw.org/manual/http11/caching" target="_blank" rel="noreferrer">HTTP 缓存对 <code>Authorization</code> 的默认约束</a>一致——带凭据的响应默认不该进共享缓存。</p><h2 id="proxy-cache-methods" tabindex="-1">proxy_cache_methods <a class="header-anchor" href="#proxy-cache-methods" aria-label="Permalink to &quot;proxy\\_cache\\_methods&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>默认:    proxy_cache_methods GET HEAD;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>默认只缓存 GET 与 HEAD</strong>，与 <a href="https://daiw.org/manual/http11/methods" target="_blank" rel="noreferrer">HTTP 的方法可缓存性</a>一致。加 <code>POST</code> 需谨慎——POST 不幂等，缓存它需要确信语义安全。</p><h2 id="upstream-cache-status" tabindex="-1">$upstream_cache_status <a class="header-anchor" href="#upstream-cache-status" aria-label="Permalink to &quot;$upstream\\_cache\\_status&quot;">​</a></h2><p>排查缓存必看的变量，值：</p><table tabindex="0"><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td><code>MISS</code></td><td>未命中，已回源</td></tr><tr><td><code>HIT</code></td><td>命中</td></tr><tr><td><code>EXPIRED</code></td><td>命中但已过期，已回源</td></tr><tr><td><code>STALE</code></td><td>返回了过期内容（<code>use_stale</code> 生效）</td></tr><tr><td><code>UPDATING</code></td><td>正在更新，返回了旧的</td></tr><tr><td><code>REVALIDATED</code></td><td>条件请求验证后确认仍有效</td></tr><tr><td><code>BYPASS</code></td><td>被 <code>proxy_cache_bypass</code> 绕过</td></tr></tbody></table><p>调试时加进响应头与日志：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_header X-Cache-Status $upstream_cache_status always;</span></span>
<span class="line"><span>log_format cache &#39;$remote_addr [$time_local] &quot;$request&quot; &#39;</span></span>
<span class="line"><span>                 &#39;$status $body_bytes_sent &#39;</span></span>
<span class="line"><span>                 &#39;cache=$upstream_cache_status rt=$request_time&#39;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="一份完整缓存配置" tabindex="-1">一份完整缓存配置 <a class="header-anchor" href="#一份完整缓存配置" aria-label="Permalink to &quot;一份完整缓存配置&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http {</span></span>
<span class="line"><span>    proxy_cache_path /var/cache/nginx</span></span>
<span class="line"><span>                     levels=1:2</span></span>
<span class="line"><span>                     keys_zone=web:100m</span></span>
<span class="line"><span>                     inactive=24h</span></span>
<span class="line"><span>                     max_size=10g</span></span>
<span class="line"><span>                     use_temp_path=off;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    server {</span></span>
<span class="line"><span>        location / {</span></span>
<span class="line"><span>            proxy_pass http://backend;</span></span>
<span class="line"><span>            proxy_set_header Host $host;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            proxy_cache     web;</span></span>
<span class="line"><span>            proxy_cache_key &quot;$scheme$host$request_uri&quot;;   # 含 $host</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            proxy_cache_valid 200 301 302 1h;</span></span>
<span class="line"><span>            proxy_cache_valid 404          1m;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            # 击穿防护 + 高可用</span></span>
<span class="line"><span>            proxy_cache_lock              on;</span></span>
<span class="line"><span>            proxy_cache_use_stale         error timeout updating</span></span>
<span class="line"><span>                                          http_500 http_502 http_503 http_504;</span></span>
<span class="line"><span>            proxy_cache_background_update on;</span></span>
<span class="line"><span>            proxy_cache_revalidate        on;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            # 登录用户不走缓存</span></span>
<span class="line"><span>            proxy_cache_bypass $http_authorization $cookie_session;</span></span>
<span class="line"><span>            proxy_no_cache     $http_authorization $cookie_session;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>            add_header X-Cache-Status $upstream_cache_status always;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/static-perf">压缩与静态文件</a>。</p>`,80)])])}const b=s(t,[["render",i]]);export{u as __pageData,b as default};
